import React, { useState } from 'react';
import { MapContainer, TileLayer, CircleMarker } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import { MapPin, Thermometer } from 'lucide-react';

const SatelliteImagery = ({ satelliteData, cityName, center, heatZones = [] }) => {
  const [activeView, setActiveView] = useState('thermal');

  if (!satelliteData) {
    return (
      <div className="flex items-center justify-center h-64 bg-gray-100 rounded-lg">
        <p className="text-gray-600">Satellite imagery not available</p>
      </div>
    );
  }

  const views = [
    { id: 'thermal', name: 'Thermal View', icon: Thermometer, color: 'bg-red-500' },
    { id: 'heat_map', name: 'Heat Map', icon: MapPin, color: 'bg-orange-500' }
  ];


  const apiKey = process.env.REACT_APP_GOOGLE_MAPS_API_KEY || "";


  return (
    <div className="space-y-4">
      <h3 className="text-lg font-semibold text-gray-800">Satellite Imagery Analysis</h3>

      {/* View selector */}
      <div className="flex space-x-2 mb-4">
        {views.map((view) => {
          const Icon = view.icon;
          return (
            <button
              key={view.id}
              onClick={() => setActiveView(view.id)}
              className={`flex items-center space-x-2 px-4 py-2 rounded-lg transition-colors ${
                activeView === view.id
                  ? 'bg-blue-100 text-blue-700 border-2 border-blue-300'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              <Icon className="w-4 h-4" />
              <span className="text-sm font-medium">{view.name}</span>
            </button>
          );
        })}
      </div>

      {/* Image display */}
      <div className="relative">
        {activeView === 'thermal' && (
          <div className="space-y-4">
            <div className="relative rounded-lg overflow-hidden border" style={{height: 320}}>
              <MapContainer center={[center.lat, center.lng]} zoom={12} style={{height: '100%', width: '100%'}}>
                <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" attribution="&copy; OpenStreetMap" />
                {heatZones.map((z, idx) => {
                  const intensity = z.intensity || 0.5;
                  const color = intensity > 0.8 ? '#dc2626' : intensity > 0.6 ? '#ea580c' : intensity > 0.4 ? '#eab308' : '#16a34a';
                  const radius = 80 + intensity * 120;
                  return (
                    <CircleMarker
                      key={idx}
                      center={[z.lat, z.lng]}
                      pathOptions={{ color, fillColor: color, fillOpacity: 0.35 }}
                      radius={radius / 20}
                    />
                  );
                })}
              </MapContainer>
              <div className="absolute top-2 left-2 bg-black bg-opacity-70 text-white px-3 py-1 rounded-lg text-sm">
                🔥 Thermal-style Intensity (Leaflet)
              </div>
            </div>
            <p className="text-sm text-gray-600">
              Thermal satellite imagery showing heat distribution across {cityName}. 
              Red areas indicate higher surface temperatures.
            </p>
          </div>
        )}

        {activeView === 'heat_map' && (
          <div className="space-y-4">
            <div className="relative rounded-lg overflow-hidden border" style={{height: 320}}>
              <MapContainer center={[center.lat, center.lng]} zoom={12} style={{height: '100%', width: '100%'}}>
                <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" attribution="&copy; OpenStreetMap" />
              </MapContainer>
              <div className="absolute top-2 left-2 bg-black bg-opacity-70 text-white px-3 py-1 rounded-lg text-sm">
                🌡️ Heat Map (Leaflet Heat)
              </div>
            </div>
            <p className="text-sm text-gray-600">
              Heat map overlay showing urban heat island intensity. Warmer colors indicate areas with higher heat retention.
            </p>
          </div>
        )}

      </div>

      {/* Analysis insights */}
      <div className="bg-blue-50 rounded-lg p-4">
        <h4 className="font-semibold text-blue-900 mb-2">📊 Analysis Insights</h4>
        <ul className="text-sm text-blue-800 space-y-1">
          <li>• Urban areas show 3-5°C higher temperatures than surrounding rural areas</li>
          <li>• Industrial zones exhibit the highest heat intensity</li>
          <li>• Green spaces provide significant cooling effects</li>
          <li>• Building density correlates with heat retention</li>
        </ul>
      </div>
    </div>
  );
};

export default SatelliteImagery;
